package com.demo;

import org.junit.jupiter.api.Test;
import org.springframework.boot.builder.SpringApplicationBuilder;

import static org.junit.jupiter.api.Assertions.*;

class ServletInitializerTests {

    @Test
    void testConfigureReturnsNonNullBuilder() {
        ServletInitializer initializer = new ServletInitializer();
        SpringApplicationBuilder builder = new SpringApplicationBuilder();

        SpringApplicationBuilder result = initializer.configure(builder);

        assertNotNull(result);
    }

    @Test
    void testConfigureReturnsSameBuilderInstance() {
        ServletInitializer initializer = new ServletInitializer();
        SpringApplicationBuilder builder = new SpringApplicationBuilder();

        SpringApplicationBuilder result = initializer.configure(builder);

        assertSame(builder, result);
    }

    @Test
    void testConfigureWithNullBuilder() {
        ServletInitializer initializer = new ServletInitializer();

        assertThrows(NullPointerException.class, () -> {
            initializer.configure(null);
        });
    }

    @Test
    void testConfigureConfiguresSourcesCorrectly() {
        ServletInitializer initializer = new ServletInitializer();
        SpringApplicationBuilder builder = new SpringApplicationBuilder();

        SpringApplicationBuilder result = initializer.configure(builder);

        assertNotNull(result);
        assertTrue(result.application().getAllSources().contains(BootDemoApplication.class));
    }
}
